const row = $input.first().json || {};
const q = $('Job Review Page').first().json.query || {};

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const DASHBOARD_URL = 'http://localhost:5173/recruiter';

const shell = (body) => `<!DOCTYPE html>
<html lang="en"><head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Review job - Shortlist</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500..800&family=Instrument+Sans:wght@400..700&display=swap" rel="stylesheet">
<style>
  :root{
    --ink:#12213b; --ink-soft:#1d3258; --fog:#f3f5f9; --line:#d3dae6; --steel:#56657e;
    --hl:#ffd93d; --hl-soft:#fff3b8; --danger:#b3261e; --danger-bg:#fdecea;
    --ok:#075e4b; --ok-bg:#d4f0e6;
    --display:'Bricolage Grotesque','Segoe UI',system-ui,sans-serif;
    --body:'Instrument Sans',system-ui,-apple-system,'Segoe UI',sans-serif;
  }
  *{box-sizing:border-box}
  body {
  margin: 0;
  padding: 24px 32px 48px;
  background: var(--fog);
  color: var(--ink);
  font-family: var(--body);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
  input,select,textarea,button{font:inherit;color:inherit}
  .wrap {
  width: 100%;
  max-width: none;
  margin: 0;
}
  .brand{display:inline-flex;align-items:center;gap:10px;margin-bottom:20px;font-family:var(--display);
    font-weight:700;font-size:20px;letter-spacing:-.02em}
  .brand svg{width:32px;height:32px}
  .card {
  width: 100%;
  background: #fff;
  border: 1px solid var(--line);
  border-top: 4px solid var(--hl);
  border-radius: 12px;
  padding: 36px 40px 40px;
}
  .done{padding:8px 0 4px}
  .okmark{width:44px;height:44px;margin-bottom:16px;border-radius:50%;background:var(--ok-bg);color:var(--ok);
    display:flex;align-items:center;justify-content:center}
  .okmark svg{width:22px;height:22px}
  h1{margin:0 0 6px;font-family:var(--display);font-size:28px;font-weight:700;line-height:1.1;letter-spacing:-.025em}
  h2{margin:32px 0 8px;font-family:var(--display);font-size:19px;font-weight:700;letter-spacing:-.015em}
  .sub{margin:0 0 16px;color:var(--steel)}
  .note{margin:0 0 8px;padding:12px 14px;background:var(--fog);border-left:3px solid var(--hl);
    border-radius:6px;font-size:15px}
  .tablewrap{position:relative;overflow-x:auto;padding:0 0 4px}
  table{width:100%;min-width:640px;border-collapse:collapse;font-size:14px}
  th{padding:10px 8px;background:var(--fog);color:var(--steel);font-weight:600;text-align:left}
  th:first-child{border-radius:8px 0 0 8px;padding-left:12px} th:last-child{border-radius:0 8px 8px 0}
  td{padding:8px;border-bottom:1px solid var(--line);vertical-align:middle}
  input[type=text],input[type=number],select,textarea{width:100%;height:42px;padding:0 12px;border:1.5px solid var(--line);
    border-radius:8px;background:#fff;font-size:15px;transition:border-color .15s,box-shadow .15s}
  select{padding-right:8px}
  textarea{height:auto;padding:12px 14px;resize:vertical;line-height:1.5}
  input:hover,select:hover,textarea:hover{border-color:#b3bdcf}
  input:focus-visible,select:focus-visible,textarea:focus-visible{border-color:var(--ink);outline:2px solid transparent;
    box-shadow:0 0 0 3px var(--hl)}
  label.f{display:block;margin:20px 0 6px;font-size:14px;font-weight:600}
  .grid{display:grid;grid-template-columns:1fr 2fr;gap:16px}
  .pill{display:inline-block;padding:2px 10px;border-radius:999px;font-size:12px;font-weight:700;
    background:var(--hl-soft);color:var(--ink);white-space:nowrap}
  .pill.jd{background:var(--ok-bg);color:var(--ok)}
  button{cursor:pointer;border:0;border-radius:8px;font-weight:600;transition:background-color .15s}
  button:focus-visible{outline:3px solid var(--ink);outline-offset:2px}
  #go{margin-top:28px;width:100%;height:48px;background:var(--ink);color:#fff}
  #go:hover:not(:disabled){background:var(--ink-soft)}
  #go:disabled{opacity:.55;cursor:wait}
  .ghost{height:40px;margin-top:12px;padding:0 16px;background:#fff;border:1.5px solid var(--line);color:var(--ink)}
  .ghost:hover{background:var(--fog);border-color:#b3bdcf}
  .x{width:36px;height:36px;padding:0;background:transparent;color:var(--steel);font-size:16px}
  .x:hover{background:var(--danger-bg);color:var(--danger)}
  .errors{margin-top:20px;padding:12px 14px;background:var(--danger-bg);border-left:3px solid var(--danger);
    border-radius:6px;color:#7a1a14;font-size:15px}
  .errors[hidden]{display:none}
  .errors ul{margin:0;padding-left:20px}
  a.btn{display:inline-flex;align-items:center;height:48px;padding:0 22px;background:var(--ink);color:#fff;
    border-radius:8px;font-weight:600;text-decoration:none;transition:background-color .15s}
  a.btn:hover{background:var(--ink-soft)}
  a.btn:focus-visible{outline:3px solid var(--ink);outline-offset:2px}
  @media (max-width:640px){.card{padding:24px 18px 28px}.grid{grid-template-columns:1fr}a.btn{width:100%;justify-content:center}}
  @media (prefers-reduced-motion:reduce){*{transition:none!important}}
</style></head><body>
<div class="wrap">
<div class="brand">
  <svg viewBox="0 0 32 32" aria-hidden="true">
    <rect width="32" height="32" rx="8" fill="#12213B"/>
    <rect x="9" y="6" width="14" height="20" rx="2" fill="#F7F8FB"/>
    <rect x="11.5" y="10" width="9" height="2" rx="1" fill="#9AA6BA"/>
    <rect x="8" y="14.5" width="16" height="4.5" rx="1" fill="#FFD93D" opacity=".92"/>
    <rect x="11.5" y="15.5" width="9" height="2" rx="1" fill="#12213B"/>
    <rect x="11.5" y="21" width="6" height="2" rx="1" fill="#9AA6BA"/>
  </svg>
  Shortlist
</div>
${body}
</div></body></html>`;

const msg = (title, text) => [{ json: { html: shell(`<div class="card"><h1>${esc(title)}</h1><p class="sub" style="margin:0">${esc(text)}</p></div>`) } }];

if (!row.jobId || row.jobId !== q.jobId || !q.token || String(row.reviewToken) !== String(q.token)) {
  return msg('This link is not valid', 'It may have expired or already been used.');
}
if (row.status !== 'Draft') {
  return msg('Already processed', 'This job has already been approved.');
}

let skills = [];
try { skills = JSON.parse(row.draftSkills || '[]'); } catch (e) {}

const data = {
  jobId: row.jobId,
  token: String(q.token),
  skills,
  minExperienceYears: Number(row.minExperienceYears) || 0,
  education: row.education || ''
};
const dataJson = JSON.stringify(data).replace(/</g, '\\u003c');

const tgBox = row.telegramPost
  ? `<label class="f" for="tg">Telegram post</label><textarea id="tg" rows="9">${esc(row.telegramPost)}</textarea>` : '';
const liBox = row.linkedinPost
  ? `<label class="f" for="li">LinkedIn post</label><textarea id="li" rows="11">${esc(row.linkedinPost)}</textarea>` : '';

const page = `
<div class="card" id="main">
  <h1>Review &amp; approve</h1>
  <p class="sub">${esc(row.role)} · Job ID <strong>${esc(row.jobId)}</strong></p>
  <div class="note" id="note"></div>

  <h2>Skills &amp; weights</h2>
  <p class="sub" style="margin-bottom:12px">10 = essential, 1 = minor. Weights are private and never appear in the posts.</p>
  <div class="tablewrap">
  <table>
    <thead><tr><th>Skill</th><th>Weight (1-10)</th><th>Type</th><th>Source</th><th><span style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)">Remove</span></th></tr></thead>
    <tbody id="rows"></tbody>
  </table>
  </div>
  <button class="ghost" id="add">+ Add skill</button>

  <h2>Requirements</h2>
  <div class="grid">
    <div><label class="f" style="margin-top:0" for="years">Minimum years</label><input type="number" id="years" min="0" max="30"></div>
    <div><label class="f" style="margin-top:0" for="edu">Education</label><input type="text" id="edu" maxlength="200"></div>
  </div>

  <h2>Posts</h2>
  ${tgBox}${liBox}

  <div class="errors" id="errors" role="alert" hidden></div>
  <button id="go">Approve &amp; publish</button>
</div>

<script>
var D = ${dataJson};
var DASHBOARD_URL = ${JSON.stringify(DASHBOARD_URL)};
var skills = D.skills.map(function(s){ return {skill: s.skill, weight: s.weight, type: s.type, source: s.source}; });
var api = location.pathname.replace('job-review', 'job-approve');
function $(id){ return document.getElementById(id); }
function esc(s){ return String(s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }

$('years').value = D.minExperienceYears;
$('edu').value = D.education;
var anyJD = skills.some(function(s){ return s.source === 'jd'; });
$('note').textContent = anyJD
  ? 'Some weights were taken from your job description (green). The rest are AI suggestions (yellow). Adjust anything you like.'
  : 'These weights are AI suggestions. Adjust anything you like.';

function render(){
  $('rows').innerHTML = skills.map(function(s, i){
    var label = s.source === 'jd' ? 'from your JD' : (s.source === 'added' ? 'added by you' : 'AI suggestion');
    return '<tr>' +
      '<td><input type="text" maxlength="60" aria-label="Skill name" value="' + esc(s.skill) + '" data-i="' + i + '" data-f="skill"></td>' +
      '<td style="width:110px"><input type="number" min="1" max="10" step="1" aria-label="Weight" value="' + esc(s.weight) + '" data-i="' + i + '" data-f="weight"></td>' +
      '<td style="width:150px"><select aria-label="Type" data-i="' + i + '" data-f="type"><option' + (s.type === 'Required' ? ' selected' : '') + '>Required</option><option' + (s.type !== 'Required' ? ' selected' : '') + '>Nice-to-have</option></select></td>' +
      '<td><span class="pill ' + (s.source === 'jd' ? 'jd' : '') + '">' + label + '</span></td>' +
      '<td style="width:52px"><button class="x" aria-label="Remove skill" data-del="' + i + '">✕</button></td></tr>';
  }).join('');
}
function sync(e){
  var t = e.target, i = t.getAttribute('data-i'), f = t.getAttribute('data-f');
  if (i !== null && f) skills[Number(i)][f] = t.value;
}
$('rows').addEventListener('input', sync);
$('rows').addEventListener('change', sync);
$('rows').addEventListener('click', function(e){
  var d = e.target.getAttribute('data-del');
  if (d !== null) { skills.splice(Number(d), 1); render(); }
});
$('add').addEventListener('click', function(){
  skills.push({skill: '', weight: 5, type: 'Required', source: 'added'});
  render();
});

function showErrors(list){
  $('errors').innerHTML = '<ul>' + list.map(function(e){ return '<li>' + esc(e) + '</li>'; }).join('') + '</ul>';
  $('errors').hidden = false;
}

$('go').addEventListener('click', async function(){
  var btn = this;
  $('errors').hidden = true;
  var items = skills.map(function(s){
    return {skill: String(s.skill || '').trim(), weight: Math.round(Number(s.weight)), type: s.type};
  });
  var payload = {
    jobId: D.jobId, token: D.token, skills: items,
    minExperienceYears: Number($('years').value) || 0,
    education: $('edu').value,
    telegramPost: $('tg') ? $('tg').value : '',
    linkedinPost: $('li') ? $('li').value : ''
  };
  btn.disabled = true; btn.textContent = 'Saving';

try {
  console.log('Approval API URL:', api);

  var res = await fetch(api, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  var responseText = await res.text();

  console.log('HTTP status:', res.status);
  console.log('Response:', responseText);

  var data;
  try {
    data = JSON.parse(responseText);
  } catch (parseError) {
    throw new Error(
      'Server returned non-JSON response (HTTP ' +
      res.status + '): ' + responseText.slice(0, 300)
    );
  }

  if (!res.ok) {
    throw new Error('HTTP ' + res.status + ': ' + responseText.slice(0, 300));
  }

  if (data.ok) {
    $('main').innerHTML =
      '<div class="done">' +
      '<h1>Job approved</h1>' +
      '<p class="sub">Job ID <strong>' +
      esc(data.jobId) +
      '</strong> is now open for applications.</p>' +
      '<a class="btn" href="' + esc(DASHBOARD_URL) +
      '">Back to dashboard</a></div>';
    return;
  }

  showErrors(data.errors || ['Approval failed.']);

} catch (e) {
  console.error('Approval error:', e);
  showErrors(['Approval failed: ' + e.message]);
}

btn.disabled = false;
btn.textContent = 'Approve & publish';


});

render();
</script>`;

return [{ json: { html: shell(page) } }];
